.darma-loader-darma-b17-water-clock { --accent: var(--loader-color, #0284c7); --accent-2: var(--loader-secondary-color, #a16207); width: calc(var(--loader-size, 108px) * .78); height: var(--loader-size, 108px); position: relative; }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__upper { position: absolute; left: 12%; right: 12%; top: 0; height: 38%; border-radius: 4px 4px 42% 42%; overflow: hidden; box-shadow: inset 0 0 0 3px var(--accent-2); }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__upper .darma-loader-darma-b17-water-clock__fill { position: absolute; left: 0; right: 0; top: 0; height: 88%; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); animation: darma-loader-darma-b17-water-clock-clepsy-drain calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__lower { position: absolute; left: 12%; right: 12%; bottom: 0; height: 46%; border-radius: 4px 4px 12% 12%; overflow: hidden; box-shadow: inset 0 0 0 3px var(--accent-2); }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__lower .darma-loader-darma-b17-water-clock__fill { position: absolute; left: 0; right: 0; bottom: 0; height: 6%; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); animation: darma-loader-darma-b17-water-clock-clepsy-rise calc(var(--loader-speed, 1s) * 4) linear infinite; }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__lower span { position: absolute; left: 6%; width: 26%; height: 3%; border-radius: 2px; background: color-mix(in srgb, var(--accent-2) 70%, transparent); }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__lower span:nth-of-type(1) { bottom: 26%; }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__lower span:nth-of-type(2) { bottom: 50%; }
.darma-loader-darma-b17-water-clock .darma-loader-darma-b17-water-clock__lower span:nth-of-type(3) { bottom: 74%; }
.darma-loader-darma-b17-water-clock i { position: absolute; left: 46%; top: 38%; width: 8%; height: 10%; border-radius: 50% 50% 50% 50% / 66% 66% 34% 34%; background: var(--accent); animation: darma-loader-darma-b17-water-clock-clepsy-drip calc(var(--loader-speed, 1s) * .7) linear infinite; }
@keyframes darma-loader-darma-b17-water-clock-clepsy-drain { 0%, 4% { height: 88%; } 88% { height: 4%; } 96%, 100% { height: 88%; } }
@keyframes darma-loader-darma-b17-water-clock-clepsy-rise { 0%, 4% { height: 6%; } 88% { height: 90%; } 96%, 100% { height: 6%; } }
@keyframes darma-loader-darma-b17-water-clock-clepsy-drip { 0% { opacity: 0; transform: translateY(0) scale(.6); } 20% { opacity: 1; transform: translateY(0) scale(1); } 100% { opacity: 0; transform: translateY(140%) scale(.8); } }

